CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE company(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(30) NOT NULL UNIQUE,name varchar(200) NOT NULL,base_currency char(3) NOT NULL DEFAULT 'UGX',timezone varchar(60) NOT NULL DEFAULT 'Africa/Kampala',active boolean NOT NULL DEFAULT true);
CREATE TABLE branch(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),code varchar(30) NOT NULL,name varchar(200) NOT NULL,UNIQUE(company_id,code));
CREATE TABLE warehouse(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),branch_id uuid NOT NULL REFERENCES branch(id),code varchar(30) NOT NULL,name varchar(200) NOT NULL,UNIQUE(company_id,code));
CREATE TABLE storage_location(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),warehouse_id uuid NOT NULL REFERENCES warehouse(id),code varchar(40) NOT NULL,name varchar(200) NOT NULL,type varchar(20) NOT NULL CHECK(type IN('SELLABLE','DAMAGED','QUARANTINE','EXPIRED','TRANSIT')),UNIQUE(warehouse_id,code));
CREATE TABLE category(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),name varchar(120) NOT NULL,parent_id uuid REFERENCES category(id),UNIQUE(company_id,name));
CREATE TABLE brand(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),name varchar(120) NOT NULL,UNIQUE(company_id,name));
CREATE TABLE unit_of_measure(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),code varchar(20) NOT NULL,name varchar(80) NOT NULL,precision_scale smallint NOT NULL DEFAULT 0 CHECK(precision_scale BETWEEN 0 AND 6),UNIQUE(company_id,code));
CREATE TABLE product(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),sku varchar(80) NOT NULL,name varchar(220) NOT NULL,category_id uuid REFERENCES category(id),brand_id uuid REFERENCES brand(id),tracking varchar(12) NOT NULL DEFAULT 'NONE' CHECK(tracking IN('NONE','LOT','SERIAL')),active boolean NOT NULL DEFAULT true,UNIQUE(company_id,sku));
CREATE TABLE product_variant(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),product_id uuid NOT NULL REFERENCES product(id),uom_id uuid NOT NULL REFERENCES unit_of_measure(id),sku varchar(80) NOT NULL,attributes jsonb NOT NULL DEFAULT '{}',UNIQUE(company_id,sku));
CREATE TABLE barcode(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),value varchar(100) NOT NULL,UNIQUE(company_id,value));
CREATE TABLE business_partner(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),type varchar(10) NOT NULL CHECK(type IN('SUPPLIER','CUSTOMER','BOTH')),code varchar(40) NOT NULL,name varchar(200) NOT NULL,email varchar(254),phone varchar(40),active boolean NOT NULL DEFAULT true,UNIQUE(company_id,code));
CREATE TABLE business_document(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),type varchar(25) NOT NULL,status varchar(20) NOT NULL,number varchar(50) NOT NULL,partner_id uuid REFERENCES business_partner(id),warehouse_id uuid REFERENCES warehouse(id),document_date date NOT NULL,currency char(3) NOT NULL,approved_by uuid,posted_at timestamptz,version bigint NOT NULL DEFAULT 0,UNIQUE(company_id,type,number));
CREATE TABLE business_document_line(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES business_document(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),ordered_qty numeric(19,6) NOT NULL CHECK(ordered_qty>0),processed_qty numeric(19,6) NOT NULL DEFAULT 0,unit_price numeric(19,4) NOT NULL DEFAULT 0,tax_code varchar(30),CHECK(processed_qty>=0 AND processed_qty<=ordered_qty));
CREATE TABLE inventory_movement(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES company(id),type varchar(30) NOT NULL,reference_type varchar(40) NOT NULL,reference_id uuid NOT NULL,posted_at timestamptz NOT NULL,actor_id uuid NOT NULL,reverses_movement_id uuid REFERENCES inventory_movement(id));
CREATE TABLE inventory_movement_line(id uuid PRIMARY KEY,movement_id uuid NOT NULL REFERENCES inventory_movement(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),location_id uuid NOT NULL REFERENCES storage_location(id),quantity numeric(19,6) NOT NULL CHECK(quantity>0),unit_cost numeric(19,4) NOT NULL CHECK(unit_cost>=0),lot_key varchar(100));
CREATE TABLE stock_balance(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES company(id),location_id uuid NOT NULL REFERENCES storage_location(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),lot_key varchar(100) NOT NULL DEFAULT '-',on_hand numeric(19,6) NOT NULL DEFAULT 0,reserved numeric(19,6) NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 0,CHECK(on_hand>=0),CHECK(reserved>=0 AND reserved<=on_hand),UNIQUE(company_id,location_id,product_variant_id,lot_key));
CREATE TABLE idempotency_record(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES company(id),idempotency_key varchar(120) NOT NULL,request_hash char(64) NOT NULL,response_id uuid NOT NULL,created_at timestamptz NOT NULL,UNIQUE(company_id,idempotency_key));
CREATE TABLE lot(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),lot_number varchar(100) NOT NULL,expiry_date date,UNIQUE(company_id,product_variant_id,lot_number));
CREATE TABLE serial_number(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),serial varchar(150) NOT NULL,status varchar(20) NOT NULL,UNIQUE(company_id,serial));
CREATE TABLE reorder_rule(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),warehouse_id uuid NOT NULL REFERENCES warehouse(id),product_variant_id uuid NOT NULL REFERENCES product_variant(id),minimum_qty numeric(19,6) NOT NULL,reorder_qty numeric(19,6) NOT NULL,UNIQUE(company_id,warehouse_id,product_variant_id));
CREATE TABLE audit_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES company(id),actor_id uuid,event_type varchar(80) NOT NULL,entity_type varchar(80) NOT NULL,entity_id uuid,occurred_at timestamptz NOT NULL DEFAULT now(),details jsonb NOT NULL DEFAULT '{}');
CREATE INDEX ix_movement_company_time ON inventory_movement(company_id,posted_at DESC); CREATE INDEX ix_balance_lookup ON stock_balance(company_id,product_variant_id,location_id); CREATE INDEX ix_document_search ON business_document(company_id,type,status,document_date DESC);
